export default JSON.parse("{\"workId\":\"xunzi\",\"chapter\":{\"id\":\"xunzi_ch-18\",\"workId\":\"xunzi\",\"order\":18,\"title\":\"正論\",\"difficulty\":4,\"estimatedMinutes\":16,\"passageIds\":[\"xunzi_ch-18_p-1\",\"xunzi_ch-18_p-2\",\"xunzi_ch-18_p-3\",\"xunzi_ch-18_p-4\",\"xunzi_ch-18_p-5\",\"xunzi_ch-18_p-6\",\"xunzi_ch-18_p-7\",\"xunzi_ch-18_p-8\",\"xunzi_ch-18_p-9\",\"xunzi_ch-18_p-10\",\"xunzi_ch-18_p-11\",\"xunzi_ch-18_p-12\",\"xunzi_ch-18_p-13\",\"xunzi_ch-18_p-14\",\"xunzi_ch-18_p-15\",\"xunzi_ch-18_p-16\",\"xunzi_ch-18_p-17\",\"xunzi_ch-18_p-18\",\"xunzi_ch-18_p-19\",\"xunzi_ch-18_p-20\",\"xunzi_ch-18_p-21\",\"xunzi_ch-18_p-22\",\"xunzi_ch-18_p-23\",\"xunzi_ch-18_p-24\",\"xunzi_ch-18_p-25\",\"xunzi_ch-18_p-26\",\"xunzi_ch-18_p-27\",\"xunzi_ch-18_p-28\",\"xunzi_ch-18_p-29\",\"xunzi_ch-18_p-30\",\"xunzi_ch-18_p-31\",\"xunzi_ch-18_p-32\",\"xunzi_ch-18_p-33\",\"xunzi_ch-18_p-34\",\"xunzi_ch-18_p-35\",\"xunzi_ch-18_p-36\",\"xunzi_ch-18_p-37\",\"xunzi_ch-18_p-38\",\"xunzi_ch-18_p-39\",\"xunzi_ch-18_p-40\",\"xunzi_ch-18_p-41\",\"xunzi_ch-18_p-42\",\"xunzi_ch-18_p-43\"],\"tags\":[\"儒家\",\"性惡論\",\"禮樂\"]},\"passages\":[{\"id\":\"xunzi_ch-18_p-1\",\"chapterId\":\"xunzi_ch-18\",\"order\":1,\"canonicalText\":\"世俗之為說者曰：「主道利周。」\",\"sentenceIds\":[\"xunzi_ch-18_p-1_s-1\",\"xunzi_ch-18_p-1_s-2\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"世俗的為說的人或事物說道：主道利周。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 1 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「世俗之為說者曰：「主道利周」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「世俗之為說者曰：「主道利周。」」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-2\",\"chapterId\":\"xunzi_ch-18\",\"order\":2,\"canonicalText\":\"是不然。主者、民之唱也，上者、下之儀也。彼將聽唱而應，視儀而動；唱默則民無應也，儀隱則下無動也；不應不動，則上下無以相有也。若是，則與無上同也！不祥莫大焉。故上者、下之本也。上宣明，則下治辨矣；上端誠，則下願愨矣；上公正，則下易直矣。治辨則易一，願愨則易使，易直則易知。易一則彊，易使則功，易知則明，是治之所由生也。上週密，則下疑玄矣；上幽險，則下漸詐矣；上偏曲，則下比周矣。疑玄則難一，漸詐則難使，比周則難知。難一則不彊，難使則不功，難知則不明，是亂之所由作也。故主道利明不利幽，利宣不利周。故主道明則下安，主道幽則下危。故下安則貴上，下危則賤上。故上易知，則下親上矣；上難知，則下畏上矣。下親上則上安，下畏上則上危。故主道莫惡乎難知，莫危乎使下畏己。傳曰：「惡之者眾則危。」《書》曰：「克明明德。」《詩》曰：「明明在下。」故先王明之，豈特玄之耳哉！\",\"sentenceIds\":[\"xunzi_ch-18_p-2_s-1\",\"xunzi_ch-18_p-2_s-2\",\"xunzi_ch-18_p-2_s-3\",\"xunzi_ch-18_p-2_s-4\",\"xunzi_ch-18_p-2_s-5\",\"xunzi_ch-18_p-2_s-6\",\"xunzi_ch-18_p-2_s-7\",\"xunzi_ch-18_p-2_s-8\",\"xunzi_ch-18_p-2_s-9\",\"xunzi_ch-18_p-2_s-10\",\"xunzi_ch-18_p-2_s-11\",\"xunzi_ch-18_p-2_s-12\",\"xunzi_ch-18_p-2_s-13\",\"xunzi_ch-18_p-2_s-14\",\"xunzi_ch-18_p-2_s-15\",\"xunzi_ch-18_p-2_s-16\",\"xunzi_ch-18_p-2_s-17\",\"xunzi_ch-18_p-2_s-18\",\"xunzi_ch-18_p-2_s-19\",\"xunzi_ch-18_p-2_s-20\",\"xunzi_ch-18_p-2_s-21\",\"xunzi_ch-18_p-2_s-22\",\"xunzi_ch-18_p-2_s-23\",\"xunzi_ch-18_p-2_s-24\",\"xunzi_ch-18_p-2_s-25\",\"xunzi_ch-18_p-2_s-26\",\"xunzi_ch-18_p-2_s-27\",\"xunzi_ch-18_p-2_s-28\",\"xunzi_ch-18_p-2_s-29\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"是不然。主的人或事物、民的唱啊，上的人或事物、下的儀啊。彼將聽唱而且應，視儀而且動；唱默則民無應啊，儀隱則下無動啊；不應不動，則上下無以相有啊。若是，則與無上同啊！不祥莫大焉。所以上的人或事物、下的本啊。上宣明，則下治辨矣；上端誠，則下願愨矣；上公正，則下易直矣。治辨則易一，願愨則易使，易直則易知。易一則彊，易使則功，易知則明，是治的所由生啊。上週密，則下疑玄矣；上幽險，則下漸詐矣；上偏曲，則下比周矣。疑玄則難一，漸詐則難使，比周則難知。難一則不彊，難使則不功，難知則不明，是亂的所由作啊。所以主道利明不利幽，利宣不利周。所以主道明則下安，主道幽則下危。所以下安則貴上，下危則賤上。所以上易知，則下親上矣；上難知，則下畏上矣。下親上則上安，下畏上則上危。所以主道莫惡乎難知，莫危乎使下畏己。傳說道：惡的的人或事物眾則危。《書》說道：克明明品德修養。《詩》說道：明明在下。所以先王明的，豈特玄的耳哉！\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 2 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「是不然」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「是不然。主者、民之唱也，上者、下之儀也。彼將聽唱而應……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-3\",\"chapterId\":\"xunzi_ch-18\",\"order\":3,\"canonicalText\":\"世俗之為說者曰：「桀紂有天下，湯武篡而奪之。」\",\"sentenceIds\":[\"xunzi_ch-18_p-3_s-1\",\"xunzi_ch-18_p-3_s-2\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"世俗的為說的人或事物說道：桀紂有天下，湯武篡而且奪的。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 3 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「世俗之為說者曰：「桀紂有天下，湯武篡而奪之」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「世俗之為說者曰：「桀紂有天下，湯武篡而奪之。」」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-4\",\"chapterId\":\"xunzi_ch-18\",\"order\":4,\"canonicalText\":\"是不然。以桀紂為常有天下之籍則然，親有天下之籍則不然，天下謂在桀紂則不然。\",\"sentenceIds\":[\"xunzi_ch-18_p-4_s-1\",\"xunzi_ch-18_p-4_s-2\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"是不然。以桀紂為常有天下的籍則然，親有天下的籍則不然，天下謂在桀紂則不然。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 4 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「是不然」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「是不然。以桀紂為常有天下之籍則然，親有天下之籍則不然……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-5\",\"chapterId\":\"xunzi_ch-18\",\"order\":5,\"canonicalText\":\"古者天子千官，諸侯百官。以是千官也，令行於諸夏之國，謂之王。以是百官也，令行於境內，國雖不安，不至於廢易遂亡，謂之君。聖王之子也，有天下之後也，埶籍之所在也，天下之宗室也，然而不材不中，內則百姓疾之，外則諸侯叛之，近者境內不一，遙者諸侯不聽，令不行於境內，甚者諸侯侵削之，攻伐之。若是，則雖未亡，吾謂之無天下矣。聖王沒，有埶籍者罷不足以縣天下，天下無君；諸侯有能德明威積，海內之民莫不願得以為君師；然而暴國獨侈，安能誅之，必不傷害無罪之民，誅暴國之君，若誅獨夫。若是，則可謂能用天下矣。能用天下之謂王。湯武非取天下也，脩其道，行其義，興天下之同利，除天下之同害，而天下歸之也。桀紂非去天下也，反禹湯之德，亂禮義之分，禽獸之行，積其兇，全其惡，而天下去之也。天下歸之之謂王，天下去之之謂亡。故桀紂無天下，湯武不弒君，由此效之也。湯武者，民之父母也；桀紂者、民之怨賊也。今世俗之為說者，以桀紂為君，而以湯武為弒，然則是誅民之父母，而師民之怨賊也，不祥莫大焉。以天下之合為君，則天下未嘗合於桀紂也。然則以湯武為弒，則天下未嘗有說也，直墮之耳。\",\"sentenceIds\":[\"xunzi_ch-18_p-5_s-1\",\"xunzi_ch-18_p-5_s-2\",\"xunzi_ch-18_p-5_s-3\",\"xunzi_ch-18_p-5_s-4\",\"xunzi_ch-18_p-5_s-5\",\"xunzi_ch-18_p-5_s-6\",\"xunzi_ch-18_p-5_s-7\",\"xunzi_ch-18_p-5_s-8\",\"xunzi_ch-18_p-5_s-9\",\"xunzi_ch-18_p-5_s-10\",\"xunzi_ch-18_p-5_s-11\",\"xunzi_ch-18_p-5_s-12\",\"xunzi_ch-18_p-5_s-13\",\"xunzi_ch-18_p-5_s-14\",\"xunzi_ch-18_p-5_s-15\",\"xunzi_ch-18_p-5_s-16\",\"xunzi_ch-18_p-5_s-17\",\"xunzi_ch-18_p-5_s-18\",\"xunzi_ch-18_p-5_s-19\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"古的人或事物天子千官，諸侯百官。以是千官啊，令行於諸夏的國，謂的王。以是百官啊，令行於境內，國雖不安，不至於廢易遂亡，謂的君。聖王的子啊，有天下的後啊，埶籍的所在啊，天下的宗室啊，然而且不材不中，內則百姓疾的，外則諸侯叛的，近的人或事物境內不一，遙的人或事物諸侯不聽，令不行於境內，甚的人或事物諸侯侵削的，攻伐的。若是，則雖未亡，吾謂的無天下矣。聖王沒，有埶籍的人或事物罷不足以縣天下，天下無君；諸侯有能品德修養明威積，海內的民莫不願得以為君師；然而且暴國獨侈，安能誅的，必不傷害無罪的民，誅暴國的君，若誅獨夫。若是，則可謂能用天下矣。能用天下的謂王。湯武絕不是取天下啊，脩他的道，行他的正義道義，興天下的同利，除天下的同害，而且天下歸的啊。桀紂絕不是去天下啊，反禹湯的品德修養，亂禮正義道義道品德修養規程正義道義的分，禽獸的行，積他的兇，全他的惡，而且天下去的啊。天下歸的的謂王，天下去的的謂亡。所以桀紂無天下，湯武不弒君，由此效的啊。湯武的人或事物，民的父母啊；桀紂的人或事物、民的怨賊啊。今世俗的為說的人或事物，以桀紂為君，而且以湯武為弒，然則是誅民的父母，而且師民的怨賊啊，不祥莫大焉。以天下的合為君，則天下未嘗合於桀紂啊。然則以湯武為弒，則天下未嘗有說啊，直墮的耳。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 5 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「古者天子千官，諸侯百官」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「古者天子千官，諸侯百官。以是千官也，令行於諸夏之國，……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-6\",\"chapterId\":\"xunzi_ch-18\",\"order\":6,\"canonicalText\":\"故天子唯其人。天下者，至重也，非至彊莫之能任；至大也，非至辨莫之能分；至眾也，非至明莫之能和。此三至者，非聖人莫之能盡。故非聖人莫之能王。聖人備道全美者也，是縣天下之權稱也。桀紂者、其志慮至險也，其志意至闇也，其行為至亂也；親者疏之，賢者賤之，生民怨之。禹湯之後也，而不得一人之與；刳比干，囚箕子，身死國亡，為天下之大僇，後世之言惡者必稽焉，是不容妻子之數也。故至賢疇四海，湯武是也；至罷不能容妻子，桀紂是也。今世俗之為說者，以桀紂為有天下，而臣湯武，豈不過甚矣哉！譬之，是猶傴巫跛匡大自以為有知也。\",\"sentenceIds\":[\"xunzi_ch-18_p-6_s-1\",\"xunzi_ch-18_p-6_s-2\",\"xunzi_ch-18_p-6_s-3\",\"xunzi_ch-18_p-6_s-4\",\"xunzi_ch-18_p-6_s-5\",\"xunzi_ch-18_p-6_s-6\",\"xunzi_ch-18_p-6_s-7\",\"xunzi_ch-18_p-6_s-8\",\"xunzi_ch-18_p-6_s-9\",\"xunzi_ch-18_p-6_s-10\",\"xunzi_ch-18_p-6_s-11\",\"xunzi_ch-18_p-6_s-12\",\"xunzi_ch-18_p-6_s-13\",\"xunzi_ch-18_p-6_s-14\",\"xunzi_ch-18_p-6_s-15\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"所以天子唯他的人。天下的人或事物，至重啊，絕不是至彊莫的能任；至大啊，絕不是至辨莫的能分；至眾啊，絕不是至明莫的能和。此三至的人或事物，絕不是聖人莫的能盡。所以絕不是聖人莫的能王。聖人備道全美的人或事物啊，是縣天下的權稱啊。桀紂的人或事物、他的志慮至險啊，他的志意至闇啊，他的行為至亂啊；親的人或事物疏的，賢的人或事物賤的，生民怨的。禹湯的後啊，而且不得一人的與；刳比干，囚箕子，身死國亡，為天下的大僇，後世的言惡的人或事物必稽焉，是不容妻子的數啊。所以至賢疇四海，湯武是啊；至罷不能容妻子，桀紂是啊。今世俗的為說的人或事物，以桀紂為有天下，而且臣湯武，豈不過甚矣哉！譬的，是猶傴巫跛匡大自以為有知啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 6 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「故天子唯其人」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「故天子唯其人。天下者，至重也，非至彊莫之能任；至大也……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-7\",\"chapterId\":\"xunzi_ch-18\",\"order\":7,\"canonicalText\":\"故可以有奪人國，不可以有奪人天下；可以有竊國，不可以有竊天下也。可以奪之者可以有國，而不可以有天下；竊可以得國，而不可以得天下。是何也？曰：國、小具也，可以小人有也，可以小道得也，可以小力持也；天下者、大具也，不可以小人有也，不可以小道得也，不可以小力持也。國者、小人可以有之，然而未必不亡也；天下者，至大也，非聖人莫之能有也。\",\"sentenceIds\":[\"xunzi_ch-18_p-7_s-1\",\"xunzi_ch-18_p-7_s-2\",\"xunzi_ch-18_p-7_s-3\",\"xunzi_ch-18_p-7_s-4\",\"xunzi_ch-18_p-7_s-5\",\"xunzi_ch-18_p-7_s-6\",\"xunzi_ch-18_p-7_s-7\",\"xunzi_ch-18_p-7_s-8\",\"xunzi_ch-18_p-7_s-9\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"所以可以有奪人國，不可以有奪人天下；可以有竊國，不可以有竊天下啊。可以奪的的人或事物可以有國，而且不可以有天下；竊可以得國，而且不可以得天下。是何啊？說道：國、小具啊，可以小人有啊，可以小道得啊，可以小力持啊；天下的人或事物、大具啊，不可以小人有啊，不可以小道得啊，不可以小力持啊。國的人或事物、小人可以有的，然而且未必不亡啊；天下的人或事物，至大啊，絕不是聖人莫的能有啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 7 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「故可以有奪人國，不可以有奪人天下」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「故可以有奪人國，不可以有奪人天下；可以有竊國，不可以……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-8\",\"chapterId\":\"xunzi_ch-18\",\"order\":8,\"canonicalText\":\"世俗之為說者曰：「治古無肉刑，而有象刑：墨黥，慅嬰，共、艾畢，剕、枲屨，殺、赭衣而不純。治古如是。」\",\"sentenceIds\":[\"xunzi_ch-18_p-8_s-1\",\"xunzi_ch-18_p-8_s-2\",\"xunzi_ch-18_p-8_s-3\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"世俗的為說的人或事物說道：治古無肉刑，而且有象刑：墨黥，慅嬰，共、艾畢，剕、枲屨，殺、赭衣而且不純。治古如是。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 8 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「世俗之為說者曰：「治古無肉刑，而有象刑：墨黥，慅嬰，共、艾畢，剕、枲屨，殺、赭衣而不純」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「世俗之為說者曰：「治古無肉刑，而有象刑：墨黥，慅嬰，……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-9\",\"chapterId\":\"xunzi_ch-18\",\"order\":9,\"canonicalText\":\"是不然。以為治邪？則人固莫觸罪，非獨不用肉刑，亦不用象刑矣。以為人或觸罪矣，而直輕其刑，然則是殺人者不死，傷人者不刑也。罪至重而刑至輕，庸人不知惡矣，亂莫大焉。凡刑人之本，禁暴惡惡，且懲其未也。殺人者不死，而傷人者不刑，是謂惠暴而寬賊也，非惡惡也。故象刑殆非生於治古，並起於亂今也。\",\"sentenceIds\":[\"xunzi_ch-18_p-9_s-1\",\"xunzi_ch-18_p-9_s-2\",\"xunzi_ch-18_p-9_s-3\",\"xunzi_ch-18_p-9_s-4\",\"xunzi_ch-18_p-9_s-5\",\"xunzi_ch-18_p-9_s-6\",\"xunzi_ch-18_p-9_s-7\",\"xunzi_ch-18_p-9_s-8\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"是不然。以為治邪？則人固莫觸罪，絕不是獨不用肉刑，亦不用象刑矣。以為人或觸罪矣，而且直輕他的刑，然則是殺人的人或事物不死，傷人的人或事物不刑啊。罪至重而且刑至輕，庸人不知惡矣，亂莫大焉。凡刑人的本，禁暴惡惡，且懲他的未啊。殺人的人或事物不死，而且傷人的人或事物不刑，是謂惠暴而且寬賊啊，絕不是惡惡啊。所以象刑殆絕不是生於治古，並起於亂今啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 9 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「是不然」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「是不然。以為治邪？則人固莫觸罪，非獨不用肉刑，亦不用……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-10\",\"chapterId\":\"xunzi_ch-18\",\"order\":10,\"canonicalText\":\"治古不然。凡爵列、官職、賞慶、刑罰，皆報也，以類相從者也。一物失稱，亂之端也。夫德不稱位，能不稱官，賞不當功，罰不當罪，不祥莫大焉。昔者武王伐有商，誅紂，斷其首，縣之赤旆。夫徵暴誅悍，治之盛也。殺人者死，傷人者刑，是百王之所同也，未有知其所由來者也。\",\"sentenceIds\":[\"xunzi_ch-18_p-10_s-1\",\"xunzi_ch-18_p-10_s-2\",\"xunzi_ch-18_p-10_s-3\",\"xunzi_ch-18_p-10_s-4\",\"xunzi_ch-18_p-10_s-5\",\"xunzi_ch-18_p-10_s-6\",\"xunzi_ch-18_p-10_s-7\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"治古不然。凡爵列、官職、賞慶、刑罰，皆報啊，以類相從的人或事物啊。一物失稱，亂的端啊。夫品德修養不稱位，能不稱官，賞不當功，罰不當罪，不祥莫大焉。昔的人或事物武王伐有商，誅紂，斷他的首，縣的赤旆。夫徵暴誅悍，治的盛啊。殺人的人或事物死，傷人的人或事物刑，是百王的所同啊，未有知他的所由來的人或事物啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 10 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「治古不然」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「治古不然。凡爵列、官職、賞慶、刑罰，皆報也，以類相從……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-11\",\"chapterId\":\"xunzi_ch-18\",\"order\":11,\"canonicalText\":\"刑稱罪，則治；不稱罪，則亂。故治則刑重，亂則刑輕，犯治之罪固重，犯亂之罪固輕也。《書》曰：「刑罰世輕世重。」此之謂也。\",\"sentenceIds\":[\"xunzi_ch-18_p-11_s-1\",\"xunzi_ch-18_p-11_s-2\",\"xunzi_ch-18_p-11_s-3\",\"xunzi_ch-18_p-11_s-4\",\"xunzi_ch-18_p-11_s-5\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"刑稱罪，則治；不稱罪，則亂。所以治則刑重，亂則刑輕，犯治的罪固重，犯亂的罪固輕啊。《書》說道：刑罰世輕世重。此的謂啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 11 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「刑稱罪，則治」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「刑稱罪，則治；不稱罪，則亂。故治則刑重，亂則刑輕，犯……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-12\",\"chapterId\":\"xunzi_ch-18\",\"order\":12,\"canonicalText\":\"世俗之為說者曰：「湯武不善禁令。」曰：「是何也？」曰：「楚越不受制。」\",\"sentenceIds\":[\"xunzi_ch-18_p-12_s-1\",\"xunzi_ch-18_p-12_s-2\",\"xunzi_ch-18_p-12_s-3\",\"xunzi_ch-18_p-12_s-4\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"世俗的為說的人或事物說道：湯武不善禁令。說道：是何啊？說道：楚越不受制。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 12 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「世俗之為說者曰：「湯武不善禁令」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「世俗之為說者曰：「湯武不善禁令。」曰：「是何也？」曰……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-13\",\"chapterId\":\"xunzi_ch-18\",\"order\":13,\"canonicalText\":\"是不然。湯武者、至天下之善禁令者也。湯居亳，武王居鄗，皆百里之地也，天下為一，諸侯為臣，通達之屬，莫不振動從服以化順之，曷為楚越獨不受制也！\",\"sentenceIds\":[\"xunzi_ch-18_p-13_s-1\",\"xunzi_ch-18_p-13_s-2\",\"xunzi_ch-18_p-13_s-3\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"是不然。湯武的人或事物、至天下的善禁令的人或事物啊。湯居亳，武王居鄗，皆百里的地啊，天下為一，諸侯為臣，通達的屬，莫不振動從服以化順的，曷為楚越獨不受制啊！\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 13 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「是不然」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「是不然。湯武者、至天下之善禁令者也。湯居亳，武王居鄗……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-14\",\"chapterId\":\"xunzi_ch-18\",\"order\":14,\"canonicalText\":\"彼王者之制也，視形埶而制械用，稱遠邇而等貢獻，豈必齊哉！故魯人以榶，衛人用柯，齊人用一革，土地刑制不同者，械用、備飾不可不異也。故諸夏之國同服同儀，蠻、夷、戎、狄之國同服不同制。封內甸服，封外侯服，侯衛賓服，蠻夷要服，戎狄荒服。甸服者祭，侯服者祀，賓服者享，要服者貢，荒服者終王。日祭、月祀、時享、歲貢、終王，夫是之謂視形埶而制械用，稱遠近而等貢獻；是王者之制也。\",\"sentenceIds\":[\"xunzi_ch-18_p-14_s-1\",\"xunzi_ch-18_p-14_s-2\",\"xunzi_ch-18_p-14_s-3\",\"xunzi_ch-18_p-14_s-4\",\"xunzi_ch-18_p-14_s-5\",\"xunzi_ch-18_p-14_s-6\",\"xunzi_ch-18_p-14_s-7\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"彼王的人或事物的制啊，視形埶而且制械用，稱遠邇而且等貢獻，豈必齊哉！所以魯人以榶，衛人用柯，齊人用一革，土地刑制不同的人或事物，械用、備飾不可不異啊。所以諸夏的國同服同儀，蠻、夷、戎、狄的國同服不同制。封內甸服，封外侯服，侯衛賓服，蠻夷要服，戎狄荒服。甸服的人或事物祭，侯服的人或事物祀，賓服的人或事物享，要服的人或事物貢，荒服的人或事物終王。日祭、月祀、時享、歲貢、終王，這就是儒家所稱的視形埶而且制械用，稱遠近而且等貢獻；是王的人或事物的制啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 14 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「彼王者之制也，視形埶而制械用，稱遠邇而等貢獻，豈必齊哉」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「彼王者之制也，視形埶而制械用，稱遠邇而等貢獻，豈必齊……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-15\",\"chapterId\":\"xunzi_ch-18\",\"order\":15,\"canonicalText\":\"彼楚越者，且時享、歲貢，終王之屬也，必齊之日祭月祀之屬，然後曰受制邪？是規磨之說也。溝中之瘠也，則未足與及王者之制也。語曰：「淺不足與測深，愚不足與謀智，坎井之蛙，不可與語東海之樂。」此之謂也。\",\"sentenceIds\":[\"xunzi_ch-18_p-15_s-1\",\"xunzi_ch-18_p-15_s-2\",\"xunzi_ch-18_p-15_s-3\",\"xunzi_ch-18_p-15_s-4\",\"xunzi_ch-18_p-15_s-5\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"彼楚越的人或事物，且時享、歲貢，終王的屬啊，必齊的日祭月祀的屬，然後說道：受制邪？是規磨的說啊。溝中的瘠啊，則未足與及王的人或事物的制啊。語說道：淺不足與測深，愚不足與謀智，坎井的蛙，不可與語東海的樂。此的謂啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 15 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「彼楚越者，且時享、歲貢，終王之屬也，必齊之日祭月祀之屬，然後曰受制邪」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「彼楚越者，且時享、歲貢，終王之屬也，必齊之日祭月祀之……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-16\",\"chapterId\":\"xunzi_ch-18\",\"order\":16,\"canonicalText\":\"世俗之為說者曰：「堯舜擅讓。」\",\"sentenceIds\":[\"xunzi_ch-18_p-16_s-1\",\"xunzi_ch-18_p-16_s-2\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"世俗的為說的人或事物說道：堯舜擅讓。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 16 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「世俗之為說者曰：「堯舜擅讓」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「世俗之為說者曰：「堯舜擅讓。」」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-17\",\"chapterId\":\"xunzi_ch-18\",\"order\":17,\"canonicalText\":\"是不然。天子者，埶位至尊，無敵於天下，夫有誰與讓矣？道德純備，智惠甚明，南面而聽天下，生民之屬莫不震動從服以化順之。天下無隱士，無遺善，同焉者是也，異焉者非也。夫有惡擅天下矣。\",\"sentenceIds\":[\"xunzi_ch-18_p-17_s-1\",\"xunzi_ch-18_p-17_s-2\",\"xunzi_ch-18_p-17_s-3\",\"xunzi_ch-18_p-17_s-4\",\"xunzi_ch-18_p-17_s-5\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"是不然。天子的人或事物，埶位至尊，無敵於天下，夫有誰與讓矣？道品德修養純備，智惠甚明，南面而且聽天下，生民的屬莫不震動從服以化順的。天下無隱士，無遺善，同焉的人或事物是啊，異焉的人或事物絕不是啊。夫有惡擅天下矣。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 17 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「是不然」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「是不然。天子者，埶位至尊，無敵於天下，夫有誰與讓矣？……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-18\",\"chapterId\":\"xunzi_ch-18\",\"order\":18,\"canonicalText\":\"曰：「死而擅之。」\",\"sentenceIds\":[\"xunzi_ch-18_p-18_s-1\",\"xunzi_ch-18_p-18_s-2\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"說道：死而且擅的。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 18 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「曰：「死而擅之」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「曰：「死而擅之。」」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-19\",\"chapterId\":\"xunzi_ch-18\",\"order\":19,\"canonicalText\":\"是又不然。聖王在上，決德而定次，量能而授官，皆使民載其事而各得其宜。不能以義制利，不能以偽飾性，則兼以為民。聖王已沒，天下無聖，則固莫足以擅天下矣。天下有聖，而在後子者，則天下不離，朝不易位，國不更制，天下厭然，與鄉無以異也；以堯繼堯，夫又何變之有矣！聖不在後子而在三公，則天下如歸，猶復而振之矣。天下厭然，與鄉無以異也；以堯繼堯，夫又何變之有矣！唯其徙朝改制為難。故天子生則天下一隆，致順而治，論德而定次，死則能任天下者必有之矣。夫禮義之分盡矣，擅讓惡用矣哉！\",\"sentenceIds\":[\"xunzi_ch-18_p-19_s-1\",\"xunzi_ch-18_p-19_s-2\",\"xunzi_ch-18_p-19_s-3\",\"xunzi_ch-18_p-19_s-4\",\"xunzi_ch-18_p-19_s-5\",\"xunzi_ch-18_p-19_s-6\",\"xunzi_ch-18_p-19_s-7\",\"xunzi_ch-18_p-19_s-8\",\"xunzi_ch-18_p-19_s-9\",\"xunzi_ch-18_p-19_s-10\",\"xunzi_ch-18_p-19_s-11\",\"xunzi_ch-18_p-19_s-12\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"是又不然。聖王在上，決品德修養而且定次，量能而且授官，皆使民載他的事而且各得他的宜。不能以正義道義制利，不能以偽飾性，則兼以為民。聖王已沒，天下無聖，則固莫足以擅天下矣。天下有聖，而且在後子的人或事物，則天下不離，朝不易位，國不更制，天下厭然，與鄉無以異啊；以堯繼堯，夫又何變的有矣！聖不在後子而且在三公，則天下如歸，猶復而且振的矣。天下厭然，與鄉無以異啊；以堯繼堯，夫又何變的有矣！唯他的徙朝改制為難。所以天子生則天下一隆，致順而且治，論品德修養而且定次，死則能任天下的人或事物必有的矣。夫禮正義道義道品德修養規程正義道義的分盡矣，擅讓惡用矣哉！\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 19 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「是又不然」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「是又不然。聖王在上，決德而定次，量能而授官，皆使民載……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-20\",\"chapterId\":\"xunzi_ch-18\",\"order\":20,\"canonicalText\":\"曰：「老衰而擅。」\",\"sentenceIds\":[\"xunzi_ch-18_p-20_s-1\",\"xunzi_ch-18_p-20_s-2\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"說道：老衰而且擅。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 20 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「曰：「老衰而擅」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「曰：「老衰而擅。」」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-21\",\"chapterId\":\"xunzi_ch-18\",\"order\":21,\"canonicalText\":\"是又不然。血氣筋力則有衰，若夫智慮取捨則無衰。\",\"sentenceIds\":[\"xunzi_ch-18_p-21_s-1\",\"xunzi_ch-18_p-21_s-2\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"是又不然。血氣筋力則有衰，至於談到那智慮取捨則無衰。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 21 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「是又不然」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「是又不然。血氣筋力則有衰，若夫智慮取捨則無衰。」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-22\",\"chapterId\":\"xunzi_ch-18\",\"order\":22,\"canonicalText\":\"曰：「老者不堪其勞而休也。」\",\"sentenceIds\":[\"xunzi_ch-18_p-22_s-1\",\"xunzi_ch-18_p-22_s-2\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"說道：老的人或事物不堪他的勞而且休啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 22 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「曰：「老者不堪其勞而休也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「曰：「老者不堪其勞而休也。」」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-23\",\"chapterId\":\"xunzi_ch-18\",\"order\":23,\"canonicalText\":\"是又畏事者之議也。天子者埶至重而形至佚，心至愉而志無所詘，而形不為勞，尊無上矣。衣被則服五采，雜間色，重文繡，加飾之以珠玉；食飲則重大牢而備珍怪，期臭味，曼而饋，伐皋而食，雍而徹乎五祀，執薦者百餘人，侍西房；居則設張容，負依而坐，諸侯趨走乎堂下；出戶而巫覡有事，出門而宗祝有事，乘大路趨越席以養安，側載睪芷以養鼻，前有錯衡以養目，和鸞之聲，步中武象，趨中韶護以養耳，三公奉軶、持納，諸侯持輪、挾輿、先馬，大侯編後，大夫次之，小侯元士次之，庶士介而夾道，庶人隱竄，莫敢視望。居如大神，動如天帝。持老養衰，猶有善於是者與？不老者、休也，休猶有安樂恬愉如是者乎？故曰：諸侯有老，天子無老。\",\"sentenceIds\":[\"xunzi_ch-18_p-23_s-1\",\"xunzi_ch-18_p-23_s-2\",\"xunzi_ch-18_p-23_s-3\",\"xunzi_ch-18_p-23_s-4\",\"xunzi_ch-18_p-23_s-5\",\"xunzi_ch-18_p-23_s-6\",\"xunzi_ch-18_p-23_s-7\",\"xunzi_ch-18_p-23_s-8\",\"xunzi_ch-18_p-23_s-9\",\"xunzi_ch-18_p-23_s-10\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"是又畏事的人或事物的議啊。天子的人或事物埶至重而且形至佚，心至愉而且志無所詘，而且形不為勞，尊無上矣。衣被則服五采，雜間色，重文繡，加飾的以珠玉；食飲則重大牢而且備珍怪，期臭味，曼而且饋，伐皋而且食，雍而且徹乎五祀，執薦的人或事物百餘人，侍西房；居則設張容，負依而且坐，諸侯趨走乎堂下；出戶而且巫覡有事，出門而且宗祝有事，乘大路趨越席以養安，側載睪芷以養鼻，前有錯衡以養目，和鸞的聲，步中武象，趨中韶護以養耳，三公奉軶、持納，諸侯持輪、挾輿、先馬，大侯編後，大夫次的，小侯元士次的，庶士介而且夾道，庶人隱竄，莫敢視望。居如大神，動如天帝。持老養衰，猶有善於是的人或事物與？不老的人或事物、休啊，休猶有安樂恬愉如是的人或事物乎？所以古聖先賢說道：諸侯有老，天子無老。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 23 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「是又畏事者之議也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「是又畏事者之議也。天子者埶至重而形至佚，心至愉而志無……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-24\",\"chapterId\":\"xunzi_ch-18\",\"order\":24,\"canonicalText\":\"有擅國，無擅天下，古今一也。夫曰堯舜擅讓，是虛言也，是淺者之傳，陋者之說也，不知逆順之理，小大、至不至之變者也，未可與及天下之大理者也。\",\"sentenceIds\":[\"xunzi_ch-18_p-24_s-1\",\"xunzi_ch-18_p-24_s-2\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"有擅國，無擅天下，古今一啊。夫說道：堯舜擅讓，是虛言啊，是淺的人或事物的傳，陋的人或事物的說啊，不知逆順的理，小大、至不至的變的人或事物啊，未可與及天下的大理的人或事物啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 24 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「有擅國，無擅天下，古今一也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「有擅國，無擅天下，古今一也。夫曰堯舜擅讓，是虛言也，……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-25\",\"chapterId\":\"xunzi_ch-18\",\"order\":25,\"canonicalText\":\"世俗之為說者曰：「堯舜不能教化。」是何也？曰：「朱象不化。」\",\"sentenceIds\":[\"xunzi_ch-18_p-25_s-1\",\"xunzi_ch-18_p-25_s-2\",\"xunzi_ch-18_p-25_s-3\",\"xunzi_ch-18_p-25_s-4\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"世俗的為說的人或事物說道：堯舜不能教化。是何啊？說道：朱象不化。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 25 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「世俗之為說者曰：「堯舜不能教化」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「世俗之為說者曰：「堯舜不能教化。」是何也？曰：「朱象……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-26\",\"chapterId\":\"xunzi_ch-18\",\"order\":26,\"canonicalText\":\"是不然也：堯舜至天下之善教化者也。南面而聽天下，生民之屬莫不振動從服以化順之。然而朱象獨不化，是非堯舜之過，朱象之罪也。堯舜者、天下之英也；朱象者、天下之嵬，一時之瑣也。今世俗之為說者，不怪朱象，而非堯舜，豈不過甚矣哉！夫是之謂嵬說。羿蜂門者、天下之善射者也，不能以撥弓曲矢中微；王梁造父者、天下之善馭者也，不能以闢馬毀輿致遠。堯舜者、天下之善教化者也，不能使嵬瑣化。何世而無嵬？何時而無瑣？自太皞燧人莫不有也。故作者不祥，學者受其殃，非者有慶。《詩》曰：「下民之孽，匪降自天。噂沓背憎，職競由人。」此之謂也。\",\"sentenceIds\":[\"xunzi_ch-18_p-26_s-1\",\"xunzi_ch-18_p-26_s-2\",\"xunzi_ch-18_p-26_s-3\",\"xunzi_ch-18_p-26_s-4\",\"xunzi_ch-18_p-26_s-5\",\"xunzi_ch-18_p-26_s-6\",\"xunzi_ch-18_p-26_s-7\",\"xunzi_ch-18_p-26_s-8\",\"xunzi_ch-18_p-26_s-9\",\"xunzi_ch-18_p-26_s-10\",\"xunzi_ch-18_p-26_s-11\",\"xunzi_ch-18_p-26_s-12\",\"xunzi_ch-18_p-26_s-13\",\"xunzi_ch-18_p-26_s-14\",\"xunzi_ch-18_p-26_s-15\",\"xunzi_ch-18_p-26_s-16\",\"xunzi_ch-18_p-26_s-17\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"是不然啊：堯舜至天下的善教化的人或事物啊。南面而且聽天下，生民的屬莫不振動從服以化順的。然而且朱象獨不化，是絕不是堯舜的過，朱象的罪啊。堯舜的人或事物、天下的英啊；朱象的人或事物、天下的嵬，一時的瑣啊。今世俗的為說的人或事物，不怪朱象，而且絕不是堯舜，豈不過甚矣哉！這就是儒家所稱的嵬說。羿蜂門的人或事物、天下的善射的人或事物啊，不能以撥弓曲矢中微；王梁造父的人或事物、天下的善馭的人或事物啊，不能以闢馬毀輿致遠。堯舜的人或事物、天下的善教化的人或事物啊，不能使嵬瑣化。何世而且無嵬？何時而且無瑣？自太皞燧人莫不有啊。所以作的人或事物不祥，學的人或事物受他的殃，絕不是的人或事物有慶。《詩》說道：下民的孽，匪降自天。噂沓背憎，職競由人。此的謂啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 26 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「是不然也：堯舜至天下之善教化者也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「是不然也：堯舜至天下之善教化者也。南面而聽天下，生民……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-27\",\"chapterId\":\"xunzi_ch-18\",\"order\":27,\"canonicalText\":\"世俗之為說者曰：「太古薄揹，棺厚三寸，衣衾三領，葬田不妨田，故不掘也；亂今厚葬飾棺，故抇也。」\",\"sentenceIds\":[\"xunzi_ch-18_p-27_s-1\",\"xunzi_ch-18_p-27_s-2\",\"xunzi_ch-18_p-27_s-3\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"世俗的為說的人或事物說道：太古薄揹，棺厚三寸，衣衾三領，葬田不妨田，所以不掘啊；亂今厚葬飾棺，所以抇啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 27 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「世俗之為說者曰：「太古薄揹，棺厚三寸，衣衾三領，葬田不妨田，故不掘也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「世俗之為說者曰：「太古薄揹，棺厚三寸，衣衾三領，葬田……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-28\",\"chapterId\":\"xunzi_ch-18\",\"order\":28,\"canonicalText\":\"是不及知治道，而不察於抇不抇者之所言也。凡人之盜也，必以有為，不以備不足，則以重有餘也。而聖王之生民也，皆使富厚優猶知足，而不得以有餘過度。故盜不竊，賊不刺，狗豕吐菽粟，而農賈皆能以貨財讓。風俗之美，男女自不取於塗，而百姓羞拾遺。故孔子曰：「天下有道，盜其先變乎！」雖珠玉滿體，文繡充棺，黃金充槨，加之以丹矸，重之以曾青，犀象以為樹，琅玕、龍茲、華覲以為實，人猶莫之抇也。是何故也？則求利之詭緩，而犯分之羞大也。\",\"sentenceIds\":[\"xunzi_ch-18_p-28_s-1\",\"xunzi_ch-18_p-28_s-2\",\"xunzi_ch-18_p-28_s-3\",\"xunzi_ch-18_p-28_s-4\",\"xunzi_ch-18_p-28_s-5\",\"xunzi_ch-18_p-28_s-6\",\"xunzi_ch-18_p-28_s-7\",\"xunzi_ch-18_p-28_s-8\",\"xunzi_ch-18_p-28_s-9\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"是不及知治道，而且不察於抇不抇的人或事物的所言啊。凡人的盜啊，必以有為，不以備不足，則以重有餘啊。而且聖王的生民啊，皆使富厚優猶知足，而且不得以有餘過度。所以盜不竊，賊不刺，狗豕吐菽粟，而且農賈皆能以貨財讓。風俗的美，男女自不取於塗，而且百姓羞拾遺。所以孔子說道：天下有道，盜他的先變乎！雖珠玉滿體，文繡充棺，黃金充槨，加的以丹矸，重的以曾青，犀象以為樹，琅玕、龍茲、華覲以為實，人猶莫的抇啊。是何所以啊？則求利的詭緩，而且犯分的羞大啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 28 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「是不及知治道，而不察於抇不抇者之所言也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「是不及知治道，而不察於抇不抇者之所言也。凡人之盜也，……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-29\",\"chapterId\":\"xunzi_ch-18\",\"order\":29,\"canonicalText\":\"夫亂今然後反是。上以無法使，下以無度行；知者不得慮，能者不得治，賢者不得使。若是，則上失天性，下失地利，中失人和。故百事廢，財物詘，而禍亂起。王公則病不足於上，庶人則凍餧羸瘠於下。於是焉桀紂羣居，而盜賊擊奪以危上矣。安禽獸行，虎狼貪，故脯巨人而炙嬰兒矣。若是則有何尤抇人之墓，抉人之口而求利矣哉！雖此裸而薶之，猶且必抇也，安得葬薶哉！彼乃將食其肉而齕其骨也。\",\"sentenceIds\":[\"xunzi_ch-18_p-29_s-1\",\"xunzi_ch-18_p-29_s-2\",\"xunzi_ch-18_p-29_s-3\",\"xunzi_ch-18_p-29_s-4\",\"xunzi_ch-18_p-29_s-5\",\"xunzi_ch-18_p-29_s-6\",\"xunzi_ch-18_p-29_s-7\",\"xunzi_ch-18_p-29_s-8\",\"xunzi_ch-18_p-29_s-9\",\"xunzi_ch-18_p-29_s-10\",\"xunzi_ch-18_p-29_s-11\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"夫亂今然後反是。上以無國家典章法度使，下以無度行；知的人或事物不得慮，能的人或事物不得治，賢的人或事物不得使。若是，則上失天性，下失地利，中失人和。所以百事廢，財物詘，而且禍亂起。王公則病不足於上，庶人則凍餧羸瘠於下。於是焉桀紂羣居，而且盜賊擊奪以危上矣。安禽獸行，虎狼貪，所以脯巨人而且炙嬰兒矣。若是則有何尤抇人的墓，抉人的口而且求利矣哉！雖此裸而且薶的，猶且必抇啊，安得葬薶哉！彼乃將食他的肉而且齕他的骨啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 29 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「夫亂今然後反是」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「夫亂今然後反是。上以無法使，下以無度行；知者不得慮，……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-30\",\"chapterId\":\"xunzi_ch-18\",\"order\":30,\"canonicalText\":\"夫曰：太古薄揹，故不抇也；亂今厚葬，故抇也。是特姦人之誤於亂說，以欺愚者而淖陷之，以偷取利焉。夫是之謂大姦。傳曰：「危人而自安，害人而自利。」此之謂也。\",\"sentenceIds\":[\"xunzi_ch-18_p-30_s-1\",\"xunzi_ch-18_p-30_s-2\",\"xunzi_ch-18_p-30_s-3\",\"xunzi_ch-18_p-30_s-4\",\"xunzi_ch-18_p-30_s-5\",\"xunzi_ch-18_p-30_s-6\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"夫說道：太古薄揹，所以不抇啊；亂今厚葬，所以抇啊。是特姦人的誤於亂說，以欺愚的人或事物而且淖陷的，以偷取利焉。這就是儒家所稱的大姦。傳說道：危人而且自安，害人而且自利。此的謂啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 30 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「夫曰：太古薄揹，故不抇也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「夫曰：太古薄揹，故不抇也；亂今厚葬，故抇也。是特姦人……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-31\",\"chapterId\":\"xunzi_ch-18\",\"order\":31,\"canonicalText\":\"子宋子曰：「明見侮之不辱，使人不鬥。人皆以見侮為辱，故鬥於也；知見侮之為不辱，則不鬥矣。」\",\"sentenceIds\":[\"xunzi_ch-18_p-31_s-1\",\"xunzi_ch-18_p-31_s-2\",\"xunzi_ch-18_p-31_s-3\",\"xunzi_ch-18_p-31_s-4\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"子宋子說道：明見侮的不辱，使人不鬥。人皆以見侮為辱，所以鬥於啊；知見侮的為不辱，則不鬥矣。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 31 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「子宋子曰：「明見侮之不辱，使人不鬥」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「子宋子曰：「明見侮之不辱，使人不鬥。人皆以見侮為辱，……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-32\",\"chapterId\":\"xunzi_ch-18\",\"order\":32,\"canonicalText\":\"應之曰：然則以人之情為不惡侮乎？\",\"sentenceIds\":[\"xunzi_ch-18_p-32_s-1\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"應的說道：然則以人的情為不惡侮乎？\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 32 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「應之曰：然則以人之情為不惡侮乎」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「應之曰：然則以人之情為不惡侮乎？」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-33\",\"chapterId\":\"xunzi_ch-18\",\"order\":33,\"canonicalText\":\"曰：「惡而不辱也。」\",\"sentenceIds\":[\"xunzi_ch-18_p-33_s-1\",\"xunzi_ch-18_p-33_s-2\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"說道：惡而且不辱啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 33 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「曰：「惡而不辱也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「曰：「惡而不辱也。」」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-34\",\"chapterId\":\"xunzi_ch-18\",\"order\":34,\"canonicalText\":\"曰：若是，則必不得所求焉。凡人之鬥也，必以其惡之為說，非以其辱之為故也。今俳優、侏儒、狎徒詈侮而不鬥者，是豈鉅知見侮之為不辱哉。然而不鬥者，不惡故也。今人或入其央瀆，竊其豬彘，則援劍戟而逐之，不避死傷。是豈以喪豬為辱也哉！然而不憚鬥者，惡之故也。雖以見侮為辱也，不惡則不鬥；雖知見侮為不辱，惡之則必鬥。然則鬥與不鬥邪，亡於辱之與不辱也，乃在於惡之與不惡也。夫今子宋子不能解人之惡侮，而務說人以勿辱也，豈不過甚矣哉！金舌弊口，猶將無益也。不知其無益，則不知；知其無益也，直以欺人，則不仁。不仁不知，辱莫大焉。將以為有益於人，則與無益於人也，則得大辱而退耳！說莫病是矣。\",\"sentenceIds\":[\"xunzi_ch-18_p-34_s-1\",\"xunzi_ch-18_p-34_s-2\",\"xunzi_ch-18_p-34_s-3\",\"xunzi_ch-18_p-34_s-4\",\"xunzi_ch-18_p-34_s-5\",\"xunzi_ch-18_p-34_s-6\",\"xunzi_ch-18_p-34_s-7\",\"xunzi_ch-18_p-34_s-8\",\"xunzi_ch-18_p-34_s-9\",\"xunzi_ch-18_p-34_s-10\",\"xunzi_ch-18_p-34_s-11\",\"xunzi_ch-18_p-34_s-12\",\"xunzi_ch-18_p-34_s-13\",\"xunzi_ch-18_p-34_s-14\",\"xunzi_ch-18_p-34_s-15\",\"xunzi_ch-18_p-34_s-16\",\"xunzi_ch-18_p-34_s-17\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"說道：若是，則必不得所求焉。凡人的鬥啊，必以他的惡的為說，絕不是以他的辱的為所以啊。今俳優、侏儒、狎徒詈侮而且不鬥的人或事物，是豈鉅知見侮的為不辱哉。然而且不鬥的人或事物，不惡所以啊。今人或入他的央瀆，竊他的豬彘，則援劍戟而且逐的，不避死傷。是豈以喪豬為辱啊哉！然而且不憚鬥的人或事物，惡的所以啊。雖以見侮為辱啊，不惡則不鬥；雖知見侮為不辱，惡的則必鬥。然則鬥與不鬥邪，亡於辱的與不辱啊，乃在於惡的與不惡啊。夫今子宋子不能解人的惡侮，而且務說人以勿辱啊，豈不過甚矣哉！金舌弊口，猶將無益啊。不知他的無益，則不知；知他的無益啊，直以欺人，則不仁愛慈悲之德。不仁愛慈悲之德不知，辱莫大焉。將以為有益於人，則與無益於人啊，則得大辱而且退耳！說莫病是矣。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 34 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「曰：若是，則必不得所求焉」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「曰：若是，則必不得所求焉。凡人之鬥也，必以其惡之為說……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-35\",\"chapterId\":\"xunzi_ch-18\",\"order\":35,\"canonicalText\":\"子宋子曰：「見侮不辱。」\",\"sentenceIds\":[\"xunzi_ch-18_p-35_s-1\",\"xunzi_ch-18_p-35_s-2\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"子宋子說道：見侮不辱。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 35 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「子宋子曰：「見侮不辱」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「子宋子曰：「見侮不辱。」」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-36\",\"chapterId\":\"xunzi_ch-18\",\"order\":36,\"canonicalText\":\"應之曰：凡議必先立隆正，然後可也。無隆正則是非不分，而辨訟不決，故所聞曰：「天下之大隆，是非之封界，分職名象之所起，王制是也。」故凡言議期命是非，以聖王為師。而聖王之分，榮辱是也。\",\"sentenceIds\":[\"xunzi_ch-18_p-36_s-1\",\"xunzi_ch-18_p-36_s-2\",\"xunzi_ch-18_p-36_s-3\",\"xunzi_ch-18_p-36_s-4\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"應的說道：凡議必先立隆正，然後可啊。無隆正則是絕不是不分，而且辨訟不決，所以所聞說道：天下的大隆，是絕不是的封界，分職名象的所起，王制是啊。所以凡言議期命是絕不是，以聖王為師。而且聖王的分，榮辱是啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 36 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「應之曰：凡議必先立隆正，然後可也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「應之曰：凡議必先立隆正，然後可也。無隆正則是非不分，……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-37\",\"chapterId\":\"xunzi_ch-18\",\"order\":37,\"canonicalText\":\"是有兩端矣。有義榮者，有埶榮者；有義辱者，有埶辱者。志意脩，德行厚，知慮明，是榮之由中出者也，夫是之謂義榮。爵列尊，貢祿厚，形埶勝，上為天子諸侯，下為卿相士大夫，是榮之從外至者也，夫是之謂埶榮。流淫汙僈，犯分亂理，驕暴貪利，是辱之由中出者也，夫是之謂義辱。詈侮捽搏，捶笞臏腳，斬斷枯磔，藉靡後縛，是辱之由外至者也，夫是之謂埶辱。是榮辱之兩端也。\",\"sentenceIds\":[\"xunzi_ch-18_p-37_s-1\",\"xunzi_ch-18_p-37_s-2\",\"xunzi_ch-18_p-37_s-3\",\"xunzi_ch-18_p-37_s-4\",\"xunzi_ch-18_p-37_s-5\",\"xunzi_ch-18_p-37_s-6\",\"xunzi_ch-18_p-37_s-7\",\"xunzi_ch-18_p-37_s-8\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"是有兩端矣。有正義道義榮的人或事物，有埶榮的人或事物；有正義道義辱的人或事物，有埶辱的人或事物。志意脩，品德修養行厚，知慮明，是榮的由中出的人或事物啊，這就是儒家所稱的正義道義榮。爵列尊，貢祿厚，形埶勝，上為天子諸侯，下為卿相士大夫，是榮的從外至的人或事物啊，這就是儒家所稱的埶榮。流淫汙僈，犯分亂理，驕暴貪利，是辱的由中出的人或事物啊，這就是儒家所稱的正義道義辱。詈侮捽搏，捶笞臏腳，斬斷枯磔，藉靡後縛，是辱的由外至的人或事物啊，這就是儒家所稱的埶辱。是榮辱的兩端啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 37 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「是有兩端矣」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「是有兩端矣。有義榮者，有埶榮者；有義辱者，有埶辱者。……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-38\",\"chapterId\":\"xunzi_ch-18\",\"order\":38,\"canonicalText\":\"故君子可以有埶辱，而不可以有義辱；小人可以有埶榮，而不可以有義榮。有埶辱無害為堯，有埶榮無害為桀。義榮埶榮，唯君子然後兼有之；義辱埶辱，唯小人然後兼有之。是榮辱之分也。聖王以為法，士大夫以為道，官人以為守，百姓以成俗，萬世不能易也。\",\"sentenceIds\":[\"xunzi_ch-18_p-38_s-1\",\"xunzi_ch-18_p-38_s-2\",\"xunzi_ch-18_p-38_s-3\",\"xunzi_ch-18_p-38_s-4\",\"xunzi_ch-18_p-38_s-5\",\"xunzi_ch-18_p-38_s-6\",\"xunzi_ch-18_p-38_s-7\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"所以君子可以有埶辱，而且不可以有正義道義辱；小人可以有埶榮，而且不可以有正義道義榮。有埶辱無害為堯，有埶榮無害為桀。正義道義榮埶榮，唯君子然後兼有的；正義道義辱埶辱，唯小人然後兼有的。是榮辱的分啊。聖王以為國家典章法度，士大夫以為道，官人以為守，百姓以成俗，萬世不能易啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 38 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「故君子可以有埶辱，而不可以有義辱」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「故君子可以有埶辱，而不可以有義辱；小人可以有埶榮，而……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-39\",\"chapterId\":\"xunzi_ch-18\",\"order\":39,\"canonicalText\":\"今子宋子則不然，獨詘容為己，慮一朝而改之，說必不行矣。譬之，是猶以塼塗塞江海也，以焦僥而戴太山也，蹎跌碎折，不待頃矣。二三子之善於子宋子者，殆不若止之，將恐得傷其體也。\",\"sentenceIds\":[\"xunzi_ch-18_p-39_s-1\",\"xunzi_ch-18_p-39_s-2\",\"xunzi_ch-18_p-39_s-3\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"今子宋子則不然，獨詘容為己，慮一朝而且改的，說必不行矣。譬的，是猶以塼塗塞江海啊，以焦僥而且戴太山啊，蹎跌碎折，不待頃矣。二三子的善於子宋子的人或事物，殆不若止的，將恐得傷他的體啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 39 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「今子宋子則不然，獨詘容為己，慮一朝而改之，說必不行矣」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「今子宋子則不然，獨詘容為己，慮一朝而改之，說必不行矣……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-40\",\"chapterId\":\"xunzi_ch-18\",\"order\":40,\"canonicalText\":\"子宋子曰：「人之情，欲寡，而皆以己之情，為欲多，是過也。」故率其羣徒，辨其談說，明其譬稱，將使人知情之慾寡也。\",\"sentenceIds\":[\"xunzi_ch-18_p-40_s-1\",\"xunzi_ch-18_p-40_s-2\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"子宋子說道：人的情，欲寡，而且皆以己的情，為欲多，是過啊。所以率他的羣徒，辨他的談說，明他的譬稱，將使人知情的慾寡啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 40 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「子宋子曰：「人之情，欲寡，而皆以己之情，為欲多，是過也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「子宋子曰：「人之情，欲寡，而皆以己之情，為欲多，是過……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-41\",\"chapterId\":\"xunzi_ch-18\",\"order\":41,\"canonicalText\":\"應之曰：然則亦以人之情為目不欲綦色，耳不欲綦聲，口不欲綦味，鼻不欲綦臭，形不欲綦佚；此五綦者，亦以人之情為不欲乎？\",\"sentenceIds\":[\"xunzi_ch-18_p-41_s-1\",\"xunzi_ch-18_p-41_s-2\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"應的說道：然則亦以人的情為目不欲綦色，耳不欲綦聲，口不欲綦味，鼻不欲綦臭，形不欲綦佚；此五綦的人或事物，亦以人的情為不欲乎？\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 41 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「應之曰：然則亦以人之情為目不欲綦色，耳不欲綦聲，口不欲綦味，鼻不欲綦臭，形不欲綦佚」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「應之曰：然則亦以人之情為目不欲綦色，耳不欲綦聲，口不……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-42\",\"chapterId\":\"xunzi_ch-18\",\"order\":42,\"canonicalText\":\"曰：「人之情，欲是已。」\",\"sentenceIds\":[\"xunzi_ch-18_p-42_s-1\",\"xunzi_ch-18_p-42_s-2\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"說道：人的情，欲是已。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 42 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「曰：「人之情，欲是已」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「曰：「人之情，欲是已。」」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-18_p-43\",\"chapterId\":\"xunzi_ch-18\",\"order\":43,\"canonicalText\":\"曰：若是，則說必不行矣。以人之情為欲，此五綦者而不欲多，譬之，是猶以人之情為欲富貴而不欲貨也，好美而惡西施也。古之人為之不然。以人之情為欲多而不欲寡，故賞以富厚而罰以殺損也。是百王之所同也。故上賢祿天下，次賢祿一國，下賢祿田邑，願愨之民完衣食。今子宋子以是之情為欲寡而不欲多也，然則先王以人之所不欲者賞，而以人之慾者罰邪？亂莫大焉。今子宋子嚴然而好說，聚人徒，立師學，成文典，然而說不免於以至治為至亂也，豈不過甚矣哉！\",\"sentenceIds\":[\"xunzi_ch-18_p-43_s-1\",\"xunzi_ch-18_p-43_s-2\",\"xunzi_ch-18_p-43_s-3\",\"xunzi_ch-18_p-43_s-4\",\"xunzi_ch-18_p-43_s-5\",\"xunzi_ch-18_p-43_s-6\",\"xunzi_ch-18_p-43_s-7\",\"xunzi_ch-18_p-43_s-8\",\"xunzi_ch-18_p-43_s-9\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"說道：若是，則說必不行矣。以人的情為欲，此五綦的人或事物而且不欲多，譬的，是猶以人的情為欲富貴而且不欲貨啊，好美而且惡西施啊。古的人為的不然。以人的情為欲多而且不欲寡，所以賞以富厚而且罰以殺損啊。是百王的所同啊。所以上賢祿天下，次賢祿一國，下賢祿田邑，願愨的民完衣食。今子宋子以是的情為欲寡而且不欲多啊，然則先王以人的所不欲的人或事物賞，而且以人的慾的人或事物罰邪？亂莫大焉。今子宋子嚴然而且好說，聚人徒，立師學，成文典，然而且說不免於以至治為至亂啊，豈不過甚矣哉！\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正論〉（第 43 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「曰：若是，則說必不行矣」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「曰：若是，則說必不行矣。以人之情為欲，此五綦者而不欲……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}}],\"sentences\":[{\"id\":\"xunzi_ch-18_p-1_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-1\",\"order\":1,\"canonicalText\":\"世俗之為說者曰：「主道利周。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-1_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-1\",\"order\":2,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-2_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-2\",\"order\":1,\"canonicalText\":\"是不然。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-2_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-2\",\"order\":2,\"canonicalText\":\"主者、民之唱也，上者、下之儀也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-2_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-2\",\"order\":3,\"canonicalText\":\"彼將聽唱而應，視儀而動；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-2_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-2\",\"order\":4,\"canonicalText\":\"唱默則民無應也，儀隱則下無動也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-2_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-2\",\"order\":5,\"canonicalText\":\"不應不動，則上下無以相有也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-2_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-2\",\"order\":6,\"canonicalText\":\"若是，則與無上同也！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-2_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-2\",\"order\":7,\"canonicalText\":\"不祥莫大焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-2_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-2\",\"order\":8,\"canonicalText\":\"故上者、下之本也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-2_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-2\",\"order\":9,\"canonicalText\":\"上宣明，則下治辨矣；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-2_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-2\",\"order\":10,\"canonicalText\":\"上端誠，則下願愨矣；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-2_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-2\",\"order\":11,\"canonicalText\":\"上公正，則下易直矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-2_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-2\",\"order\":12,\"canonicalText\":\"治辨則易一，願愨則易使，易直則易知。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-2_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-2\",\"order\":13,\"canonicalText\":\"易一則彊，易使則功，易知則明，是治之所由生也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-2_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-2\",\"order\":14,\"canonicalText\":\"上週密，則下疑玄矣；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-2_s-15\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-2\",\"order\":15,\"canonicalText\":\"上幽險，則下漸詐矣；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-2_s-16\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-2\",\"order\":16,\"canonicalText\":\"上偏曲，則下比周矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-2_s-17\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-2\",\"order\":17,\"canonicalText\":\"疑玄則難一，漸詐則難使，比周則難知。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-2_s-18\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-2\",\"order\":18,\"canonicalText\":\"難一則不彊，難使則不功，難知則不明，是亂之所由作也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-2_s-19\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-2\",\"order\":19,\"canonicalText\":\"故主道利明不利幽，利宣不利周。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-2_s-20\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-2\",\"order\":20,\"canonicalText\":\"故主道明則下安，主道幽則下危。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-2_s-21\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-2\",\"order\":21,\"canonicalText\":\"故下安則貴上，下危則賤上。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-2_s-22\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-2\",\"order\":22,\"canonicalText\":\"故上易知，則下親上矣；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-2_s-23\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-2\",\"order\":23,\"canonicalText\":\"上難知，則下畏上矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-2_s-24\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-2\",\"order\":24,\"canonicalText\":\"下親上則上安，下畏上則上危。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-2_s-25\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-2\",\"order\":25,\"canonicalText\":\"故主道莫惡乎難知，莫危乎使下畏己。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-2_s-26\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-2\",\"order\":26,\"canonicalText\":\"傳曰：「惡之者眾則危。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-2_s-27\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-2\",\"order\":27,\"canonicalText\":\"」《書》曰：「克明明德。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-2_s-28\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-2\",\"order\":28,\"canonicalText\":\"」《詩》曰：「明明在下。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-2_s-29\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-2\",\"order\":29,\"canonicalText\":\"」故先王明之，豈特玄之耳哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-3_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-3\",\"order\":1,\"canonicalText\":\"世俗之為說者曰：「桀紂有天下，湯武篡而奪之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-3_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-3\",\"order\":2,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-4_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-4\",\"order\":1,\"canonicalText\":\"是不然。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-4_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-4\",\"order\":2,\"canonicalText\":\"以桀紂為常有天下之籍則然，親有天下之籍則不然，天下謂在桀紂則不然。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-5_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-5\",\"order\":1,\"canonicalText\":\"古者天子千官，諸侯百官。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-5_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-5\",\"order\":2,\"canonicalText\":\"以是千官也，令行於諸夏之國，謂之王。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-5_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-5\",\"order\":3,\"canonicalText\":\"以是百官也，令行於境內，國雖不安，不至於廢易遂亡，謂之君。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-5_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-5\",\"order\":4,\"canonicalText\":\"聖王之子也，有天下之後也，埶籍之所在也，天下之宗室也，然而不材不中，內則百姓疾之，外則諸侯叛之，近者境內不一，遙者諸侯不聽，令不行於境內，甚者諸侯侵削之，攻伐之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-5_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-5\",\"order\":5,\"canonicalText\":\"若是，則雖未亡，吾謂之無天下矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-5_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-5\",\"order\":6,\"canonicalText\":\"聖王沒，有埶籍者罷不足以縣天下，天下無君；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-5_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-5\",\"order\":7,\"canonicalText\":\"諸侯有能德明威積，海內之民莫不願得以為君師；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-5_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-5\",\"order\":8,\"canonicalText\":\"然而暴國獨侈，安能誅之，必不傷害無罪之民，誅暴國之君，若誅獨夫。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-5_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-5\",\"order\":9,\"canonicalText\":\"若是，則可謂能用天下矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-5_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-5\",\"order\":10,\"canonicalText\":\"能用天下之謂王。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-5_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-5\",\"order\":11,\"canonicalText\":\"湯武非取天下也，脩其道，行其義，興天下之同利，除天下之同害，而天下歸之也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-5_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-5\",\"order\":12,\"canonicalText\":\"桀紂非去天下也，反禹湯之德，亂禮義之分，禽獸之行，積其兇，全其惡，而天下去之也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-5_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-5\",\"order\":13,\"canonicalText\":\"天下歸之之謂王，天下去之之謂亡。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-5_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-5\",\"order\":14,\"canonicalText\":\"故桀紂無天下，湯武不弒君，由此效之也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-5_s-15\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-5\",\"order\":15,\"canonicalText\":\"湯武者，民之父母也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-5_s-16\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-5\",\"order\":16,\"canonicalText\":\"桀紂者、民之怨賊也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-5_s-17\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-5\",\"order\":17,\"canonicalText\":\"今世俗之為說者，以桀紂為君，而以湯武為弒，然則是誅民之父母，而師民之怨賊也，不祥莫大焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-5_s-18\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-5\",\"order\":18,\"canonicalText\":\"以天下之合為君，則天下未嘗合於桀紂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-5_s-19\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-5\",\"order\":19,\"canonicalText\":\"然則以湯武為弒，則天下未嘗有說也，直墮之耳。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-6_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-6\",\"order\":1,\"canonicalText\":\"故天子唯其人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-6_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-6\",\"order\":2,\"canonicalText\":\"天下者，至重也，非至彊莫之能任；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-6_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-6\",\"order\":3,\"canonicalText\":\"至大也，非至辨莫之能分；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-6_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-6\",\"order\":4,\"canonicalText\":\"至眾也，非至明莫之能和。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-6_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-6\",\"order\":5,\"canonicalText\":\"此三至者，非聖人莫之能盡。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-6_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-6\",\"order\":6,\"canonicalText\":\"故非聖人莫之能王。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-6_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-6\",\"order\":7,\"canonicalText\":\"聖人備道全美者也，是縣天下之權稱也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-6_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-6\",\"order\":8,\"canonicalText\":\"桀紂者、其志慮至險也，其志意至闇也，其行為至亂也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-6_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-6\",\"order\":9,\"canonicalText\":\"親者疏之，賢者賤之，生民怨之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-6_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-6\",\"order\":10,\"canonicalText\":\"禹湯之後也，而不得一人之與；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-6_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-6\",\"order\":11,\"canonicalText\":\"刳比干，囚箕子，身死國亡，為天下之大僇，後世之言惡者必稽焉，是不容妻子之數也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-6_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-6\",\"order\":12,\"canonicalText\":\"故至賢疇四海，湯武是也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-6_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-6\",\"order\":13,\"canonicalText\":\"至罷不能容妻子，桀紂是也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-6_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-6\",\"order\":14,\"canonicalText\":\"今世俗之為說者，以桀紂為有天下，而臣湯武，豈不過甚矣哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-6_s-15\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-6\",\"order\":15,\"canonicalText\":\"譬之，是猶傴巫跛匡大自以為有知也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-7_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-7\",\"order\":1,\"canonicalText\":\"故可以有奪人國，不可以有奪人天下；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-7_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-7\",\"order\":2,\"canonicalText\":\"可以有竊國，不可以有竊天下也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-7_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-7\",\"order\":3,\"canonicalText\":\"可以奪之者可以有國，而不可以有天下；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-7_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-7\",\"order\":4,\"canonicalText\":\"竊可以得國，而不可以得天下。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-7_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-7\",\"order\":5,\"canonicalText\":\"是何也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-7_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-7\",\"order\":6,\"canonicalText\":\"曰：國、小具也，可以小人有也，可以小道得也，可以小力持也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-7_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-7\",\"order\":7,\"canonicalText\":\"天下者、大具也，不可以小人有也，不可以小道得也，不可以小力持也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-7_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-7\",\"order\":8,\"canonicalText\":\"國者、小人可以有之，然而未必不亡也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-7_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-7\",\"order\":9,\"canonicalText\":\"天下者，至大也，非聖人莫之能有也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-8_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-8\",\"order\":1,\"canonicalText\":\"世俗之為說者曰：「治古無肉刑，而有象刑：墨黥，慅嬰，共、艾畢，剕、枲屨，殺、赭衣而不純。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-8_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-8\",\"order\":2,\"canonicalText\":\"治古如是。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-8_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-8\",\"order\":3,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-9_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-9\",\"order\":1,\"canonicalText\":\"是不然。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-9_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-9\",\"order\":2,\"canonicalText\":\"以為治邪？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-9_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-9\",\"order\":3,\"canonicalText\":\"則人固莫觸罪，非獨不用肉刑，亦不用象刑矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-9_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-9\",\"order\":4,\"canonicalText\":\"以為人或觸罪矣，而直輕其刑，然則是殺人者不死，傷人者不刑也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-9_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-9\",\"order\":5,\"canonicalText\":\"罪至重而刑至輕，庸人不知惡矣，亂莫大焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-9_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-9\",\"order\":6,\"canonicalText\":\"凡刑人之本，禁暴惡惡，且懲其未也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-9_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-9\",\"order\":7,\"canonicalText\":\"殺人者不死，而傷人者不刑，是謂惠暴而寬賊也，非惡惡也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-9_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-9\",\"order\":8,\"canonicalText\":\"故象刑殆非生於治古，並起於亂今也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-10_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-10\",\"order\":1,\"canonicalText\":\"治古不然。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-10_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-10\",\"order\":2,\"canonicalText\":\"凡爵列、官職、賞慶、刑罰，皆報也，以類相從者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-10_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-10\",\"order\":3,\"canonicalText\":\"一物失稱，亂之端也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-10_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-10\",\"order\":4,\"canonicalText\":\"夫德不稱位，能不稱官，賞不當功，罰不當罪，不祥莫大焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-10_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-10\",\"order\":5,\"canonicalText\":\"昔者武王伐有商，誅紂，斷其首，縣之赤旆。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-10_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-10\",\"order\":6,\"canonicalText\":\"夫徵暴誅悍，治之盛也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-10_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-10\",\"order\":7,\"canonicalText\":\"殺人者死，傷人者刑，是百王之所同也，未有知其所由來者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-11_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-11\",\"order\":1,\"canonicalText\":\"刑稱罪，則治；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-11_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-11\",\"order\":2,\"canonicalText\":\"不稱罪，則亂。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-11_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-11\",\"order\":3,\"canonicalText\":\"故治則刑重，亂則刑輕，犯治之罪固重，犯亂之罪固輕也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-11_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-11\",\"order\":4,\"canonicalText\":\"《書》曰：「刑罰世輕世重。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-11_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-11\",\"order\":5,\"canonicalText\":\"」此之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-12_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-12\",\"order\":1,\"canonicalText\":\"世俗之為說者曰：「湯武不善禁令。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-12_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-12\",\"order\":2,\"canonicalText\":\"」曰：「是何也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-12_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-12\",\"order\":3,\"canonicalText\":\"」曰：「楚越不受制。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-12_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-12\",\"order\":4,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-13_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-13\",\"order\":1,\"canonicalText\":\"是不然。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-13_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-13\",\"order\":2,\"canonicalText\":\"湯武者、至天下之善禁令者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-13_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-13\",\"order\":3,\"canonicalText\":\"湯居亳，武王居鄗，皆百里之地也，天下為一，諸侯為臣，通達之屬，莫不振動從服以化順之，曷為楚越獨不受制也！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-14_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-14\",\"order\":1,\"canonicalText\":\"彼王者之制也，視形埶而制械用，稱遠邇而等貢獻，豈必齊哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-14_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-14\",\"order\":2,\"canonicalText\":\"故魯人以榶，衛人用柯，齊人用一革，土地刑制不同者，械用、備飾不可不異也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-14_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-14\",\"order\":3,\"canonicalText\":\"故諸夏之國同服同儀，蠻、夷、戎、狄之國同服不同制。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-14_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-14\",\"order\":4,\"canonicalText\":\"封內甸服，封外侯服，侯衛賓服，蠻夷要服，戎狄荒服。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-14_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-14\",\"order\":5,\"canonicalText\":\"甸服者祭，侯服者祀，賓服者享，要服者貢，荒服者終王。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-14_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-14\",\"order\":6,\"canonicalText\":\"日祭、月祀、時享、歲貢、終王，夫是之謂視形埶而制械用，稱遠近而等貢獻；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-14_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-14\",\"order\":7,\"canonicalText\":\"是王者之制也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-15_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-15\",\"order\":1,\"canonicalText\":\"彼楚越者，且時享、歲貢，終王之屬也，必齊之日祭月祀之屬，然後曰受制邪？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-15_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-15\",\"order\":2,\"canonicalText\":\"是規磨之說也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-15_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-15\",\"order\":3,\"canonicalText\":\"溝中之瘠也，則未足與及王者之制也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-15_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-15\",\"order\":4,\"canonicalText\":\"語曰：「淺不足與測深，愚不足與謀智，坎井之蛙，不可與語東海之樂。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-15_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-15\",\"order\":5,\"canonicalText\":\"」此之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-16_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-16\",\"order\":1,\"canonicalText\":\"世俗之為說者曰：「堯舜擅讓。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-16_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-16\",\"order\":2,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-17_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-17\",\"order\":1,\"canonicalText\":\"是不然。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-17_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-17\",\"order\":2,\"canonicalText\":\"天子者，埶位至尊，無敵於天下，夫有誰與讓矣？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-17_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-17\",\"order\":3,\"canonicalText\":\"道德純備，智惠甚明，南面而聽天下，生民之屬莫不震動從服以化順之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-17_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-17\",\"order\":4,\"canonicalText\":\"天下無隱士，無遺善，同焉者是也，異焉者非也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-17_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-17\",\"order\":5,\"canonicalText\":\"夫有惡擅天下矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-18_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-18\",\"order\":1,\"canonicalText\":\"曰：「死而擅之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-18_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-18\",\"order\":2,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-19_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-19\",\"order\":1,\"canonicalText\":\"是又不然。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-19_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-19\",\"order\":2,\"canonicalText\":\"聖王在上，決德而定次，量能而授官，皆使民載其事而各得其宜。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-19_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-19\",\"order\":3,\"canonicalText\":\"不能以義制利，不能以偽飾性，則兼以為民。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-19_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-19\",\"order\":4,\"canonicalText\":\"聖王已沒，天下無聖，則固莫足以擅天下矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-19_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-19\",\"order\":5,\"canonicalText\":\"天下有聖，而在後子者，則天下不離，朝不易位，國不更制，天下厭然，與鄉無以異也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-19_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-19\",\"order\":6,\"canonicalText\":\"以堯繼堯，夫又何變之有矣！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-19_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-19\",\"order\":7,\"canonicalText\":\"聖不在後子而在三公，則天下如歸，猶復而振之矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-19_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-19\",\"order\":8,\"canonicalText\":\"天下厭然，與鄉無以異也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-19_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-19\",\"order\":9,\"canonicalText\":\"以堯繼堯，夫又何變之有矣！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-19_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-19\",\"order\":10,\"canonicalText\":\"唯其徙朝改制為難。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-19_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-19\",\"order\":11,\"canonicalText\":\"故天子生則天下一隆，致順而治，論德而定次，死則能任天下者必有之矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-19_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-19\",\"order\":12,\"canonicalText\":\"夫禮義之分盡矣，擅讓惡用矣哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-20_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-20\",\"order\":1,\"canonicalText\":\"曰：「老衰而擅。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-20_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-20\",\"order\":2,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-21_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-21\",\"order\":1,\"canonicalText\":\"是又不然。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-21_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-21\",\"order\":2,\"canonicalText\":\"血氣筋力則有衰，若夫智慮取捨則無衰。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-22_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-22\",\"order\":1,\"canonicalText\":\"曰：「老者不堪其勞而休也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-22_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-22\",\"order\":2,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-23_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-23\",\"order\":1,\"canonicalText\":\"是又畏事者之議也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-23_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-23\",\"order\":2,\"canonicalText\":\"天子者埶至重而形至佚，心至愉而志無所詘，而形不為勞，尊無上矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-23_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-23\",\"order\":3,\"canonicalText\":\"衣被則服五采，雜間色，重文繡，加飾之以珠玉；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-23_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-23\",\"order\":4,\"canonicalText\":\"食飲則重大牢而備珍怪，期臭味，曼而饋，伐皋而食，雍而徹乎五祀，執薦者百餘人，侍西房；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-23_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-23\",\"order\":5,\"canonicalText\":\"居則設張容，負依而坐，諸侯趨走乎堂下；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-23_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-23\",\"order\":6,\"canonicalText\":\"出戶而巫覡有事，出門而宗祝有事，乘大路趨越席以養安，側載睪芷以養鼻，前有錯衡以養目，和鸞之聲，步中武象，趨中韶護以養耳，三公奉軶、持納，諸侯持輪、挾輿、先馬，大侯編後，大夫次之，小侯元士次之，庶士介而夾道，庶人隱竄，莫敢視望。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-23_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-23\",\"order\":7,\"canonicalText\":\"居如大神，動如天帝。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-23_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-23\",\"order\":8,\"canonicalText\":\"持老養衰，猶有善於是者與？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-23_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-23\",\"order\":9,\"canonicalText\":\"不老者、休也，休猶有安樂恬愉如是者乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-23_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-23\",\"order\":10,\"canonicalText\":\"故曰：諸侯有老，天子無老。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-24_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-24\",\"order\":1,\"canonicalText\":\"有擅國，無擅天下，古今一也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-24_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-24\",\"order\":2,\"canonicalText\":\"夫曰堯舜擅讓，是虛言也，是淺者之傳，陋者之說也，不知逆順之理，小大、至不至之變者也，未可與及天下之大理者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-25_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-25\",\"order\":1,\"canonicalText\":\"世俗之為說者曰：「堯舜不能教化。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-25_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-25\",\"order\":2,\"canonicalText\":\"」是何也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-25_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-25\",\"order\":3,\"canonicalText\":\"曰：「朱象不化。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-25_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-25\",\"order\":4,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-26_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-26\",\"order\":1,\"canonicalText\":\"是不然也：堯舜至天下之善教化者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-26_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-26\",\"order\":2,\"canonicalText\":\"南面而聽天下，生民之屬莫不振動從服以化順之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-26_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-26\",\"order\":3,\"canonicalText\":\"然而朱象獨不化，是非堯舜之過，朱象之罪也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-26_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-26\",\"order\":4,\"canonicalText\":\"堯舜者、天下之英也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-26_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-26\",\"order\":5,\"canonicalText\":\"朱象者、天下之嵬，一時之瑣也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-26_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-26\",\"order\":6,\"canonicalText\":\"今世俗之為說者，不怪朱象，而非堯舜，豈不過甚矣哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-26_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-26\",\"order\":7,\"canonicalText\":\"夫是之謂嵬說。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-26_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-26\",\"order\":8,\"canonicalText\":\"羿蜂門者、天下之善射者也，不能以撥弓曲矢中微；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-26_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-26\",\"order\":9,\"canonicalText\":\"王梁造父者、天下之善馭者也，不能以闢馬毀輿致遠。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-26_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-26\",\"order\":10,\"canonicalText\":\"堯舜者、天下之善教化者也，不能使嵬瑣化。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-26_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-26\",\"order\":11,\"canonicalText\":\"何世而無嵬？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-26_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-26\",\"order\":12,\"canonicalText\":\"何時而無瑣？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-26_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-26\",\"order\":13,\"canonicalText\":\"自太皞燧人莫不有也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-26_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-26\",\"order\":14,\"canonicalText\":\"故作者不祥，學者受其殃，非者有慶。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-26_s-15\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-26\",\"order\":15,\"canonicalText\":\"《詩》曰：「下民之孽，匪降自天。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-26_s-16\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-26\",\"order\":16,\"canonicalText\":\"噂沓背憎，職競由人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-26_s-17\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-26\",\"order\":17,\"canonicalText\":\"」此之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-27_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-27\",\"order\":1,\"canonicalText\":\"世俗之為說者曰：「太古薄揹，棺厚三寸，衣衾三領，葬田不妨田，故不掘也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-27_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-27\",\"order\":2,\"canonicalText\":\"亂今厚葬飾棺，故抇也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-27_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-27\",\"order\":3,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-28_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-28\",\"order\":1,\"canonicalText\":\"是不及知治道，而不察於抇不抇者之所言也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-28_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-28\",\"order\":2,\"canonicalText\":\"凡人之盜也，必以有為，不以備不足，則以重有餘也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-28_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-28\",\"order\":3,\"canonicalText\":\"而聖王之生民也，皆使富厚優猶知足，而不得以有餘過度。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-28_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-28\",\"order\":4,\"canonicalText\":\"故盜不竊，賊不刺，狗豕吐菽粟，而農賈皆能以貨財讓。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-28_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-28\",\"order\":5,\"canonicalText\":\"風俗之美，男女自不取於塗，而百姓羞拾遺。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-28_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-28\",\"order\":6,\"canonicalText\":\"故孔子曰：「天下有道，盜其先變乎！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-28_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-28\",\"order\":7,\"canonicalText\":\"」雖珠玉滿體，文繡充棺，黃金充槨，加之以丹矸，重之以曾青，犀象以為樹，琅玕、龍茲、華覲以為實，人猶莫之抇也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-28_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-28\",\"order\":8,\"canonicalText\":\"是何故也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-28_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-28\",\"order\":9,\"canonicalText\":\"則求利之詭緩，而犯分之羞大也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-29_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-29\",\"order\":1,\"canonicalText\":\"夫亂今然後反是。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-29_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-29\",\"order\":2,\"canonicalText\":\"上以無法使，下以無度行；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-29_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-29\",\"order\":3,\"canonicalText\":\"知者不得慮，能者不得治，賢者不得使。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-29_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-29\",\"order\":4,\"canonicalText\":\"若是，則上失天性，下失地利，中失人和。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-29_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-29\",\"order\":5,\"canonicalText\":\"故百事廢，財物詘，而禍亂起。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-29_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-29\",\"order\":6,\"canonicalText\":\"王公則病不足於上，庶人則凍餧羸瘠於下。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-29_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-29\",\"order\":7,\"canonicalText\":\"於是焉桀紂羣居，而盜賊擊奪以危上矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-29_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-29\",\"order\":8,\"canonicalText\":\"安禽獸行，虎狼貪，故脯巨人而炙嬰兒矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-29_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-29\",\"order\":9,\"canonicalText\":\"若是則有何尤抇人之墓，抉人之口而求利矣哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-29_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-29\",\"order\":10,\"canonicalText\":\"雖此裸而薶之，猶且必抇也，安得葬薶哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-29_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-29\",\"order\":11,\"canonicalText\":\"彼乃將食其肉而齕其骨也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-30_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-30\",\"order\":1,\"canonicalText\":\"夫曰：太古薄揹，故不抇也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-30_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-30\",\"order\":2,\"canonicalText\":\"亂今厚葬，故抇也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-30_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-30\",\"order\":3,\"canonicalText\":\"是特姦人之誤於亂說，以欺愚者而淖陷之，以偷取利焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-30_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-30\",\"order\":4,\"canonicalText\":\"夫是之謂大姦。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-30_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-30\",\"order\":5,\"canonicalText\":\"傳曰：「危人而自安，害人而自利。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-30_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-30\",\"order\":6,\"canonicalText\":\"」此之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-31_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-31\",\"order\":1,\"canonicalText\":\"子宋子曰：「明見侮之不辱，使人不鬥。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-31_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-31\",\"order\":2,\"canonicalText\":\"人皆以見侮為辱，故鬥於也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-31_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-31\",\"order\":3,\"canonicalText\":\"知見侮之為不辱，則不鬥矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-31_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-31\",\"order\":4,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-32_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-32\",\"order\":1,\"canonicalText\":\"應之曰：然則以人之情為不惡侮乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-33_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-33\",\"order\":1,\"canonicalText\":\"曰：「惡而不辱也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-33_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-33\",\"order\":2,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-34_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-34\",\"order\":1,\"canonicalText\":\"曰：若是，則必不得所求焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-34_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-34\",\"order\":2,\"canonicalText\":\"凡人之鬥也，必以其惡之為說，非以其辱之為故也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-34_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-34\",\"order\":3,\"canonicalText\":\"今俳優、侏儒、狎徒詈侮而不鬥者，是豈鉅知見侮之為不辱哉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-34_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-34\",\"order\":4,\"canonicalText\":\"然而不鬥者，不惡故也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-34_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-34\",\"order\":5,\"canonicalText\":\"今人或入其央瀆，竊其豬彘，則援劍戟而逐之，不避死傷。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-34_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-34\",\"order\":6,\"canonicalText\":\"是豈以喪豬為辱也哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-34_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-34\",\"order\":7,\"canonicalText\":\"然而不憚鬥者，惡之故也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-34_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-34\",\"order\":8,\"canonicalText\":\"雖以見侮為辱也，不惡則不鬥；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-34_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-34\",\"order\":9,\"canonicalText\":\"雖知見侮為不辱，惡之則必鬥。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-34_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-34\",\"order\":10,\"canonicalText\":\"然則鬥與不鬥邪，亡於辱之與不辱也，乃在於惡之與不惡也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-34_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-34\",\"order\":11,\"canonicalText\":\"夫今子宋子不能解人之惡侮，而務說人以勿辱也，豈不過甚矣哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-34_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-34\",\"order\":12,\"canonicalText\":\"金舌弊口，猶將無益也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-34_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-34\",\"order\":13,\"canonicalText\":\"不知其無益，則不知；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-34_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-34\",\"order\":14,\"canonicalText\":\"知其無益也，直以欺人，則不仁。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-34_s-15\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-34\",\"order\":15,\"canonicalText\":\"不仁不知，辱莫大焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-34_s-16\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-34\",\"order\":16,\"canonicalText\":\"將以為有益於人，則與無益於人也，則得大辱而退耳！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-34_s-17\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-34\",\"order\":17,\"canonicalText\":\"說莫病是矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-35_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-35\",\"order\":1,\"canonicalText\":\"子宋子曰：「見侮不辱。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-35_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-35\",\"order\":2,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-36_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-36\",\"order\":1,\"canonicalText\":\"應之曰：凡議必先立隆正，然後可也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-36_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-36\",\"order\":2,\"canonicalText\":\"無隆正則是非不分，而辨訟不決，故所聞曰：「天下之大隆，是非之封界，分職名象之所起，王制是也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-36_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-36\",\"order\":3,\"canonicalText\":\"」故凡言議期命是非，以聖王為師。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-36_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-36\",\"order\":4,\"canonicalText\":\"而聖王之分，榮辱是也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-37_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-37\",\"order\":1,\"canonicalText\":\"是有兩端矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-37_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-37\",\"order\":2,\"canonicalText\":\"有義榮者，有埶榮者；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-37_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-37\",\"order\":3,\"canonicalText\":\"有義辱者，有埶辱者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-37_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-37\",\"order\":4,\"canonicalText\":\"志意脩，德行厚，知慮明，是榮之由中出者也，夫是之謂義榮。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-37_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-37\",\"order\":5,\"canonicalText\":\"爵列尊，貢祿厚，形埶勝，上為天子諸侯，下為卿相士大夫，是榮之從外至者也，夫是之謂埶榮。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-37_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-37\",\"order\":6,\"canonicalText\":\"流淫汙僈，犯分亂理，驕暴貪利，是辱之由中出者也，夫是之謂義辱。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-37_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-37\",\"order\":7,\"canonicalText\":\"詈侮捽搏，捶笞臏腳，斬斷枯磔，藉靡後縛，是辱之由外至者也，夫是之謂埶辱。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-37_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-37\",\"order\":8,\"canonicalText\":\"是榮辱之兩端也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-38_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-38\",\"order\":1,\"canonicalText\":\"故君子可以有埶辱，而不可以有義辱；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-38_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-38\",\"order\":2,\"canonicalText\":\"小人可以有埶榮，而不可以有義榮。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-38_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-38\",\"order\":3,\"canonicalText\":\"有埶辱無害為堯，有埶榮無害為桀。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-38_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-38\",\"order\":4,\"canonicalText\":\"義榮埶榮，唯君子然後兼有之；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-38_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-38\",\"order\":5,\"canonicalText\":\"義辱埶辱，唯小人然後兼有之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-38_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-38\",\"order\":6,\"canonicalText\":\"是榮辱之分也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-38_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-38\",\"order\":7,\"canonicalText\":\"聖王以為法，士大夫以為道，官人以為守，百姓以成俗，萬世不能易也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-39_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-39\",\"order\":1,\"canonicalText\":\"今子宋子則不然，獨詘容為己，慮一朝而改之，說必不行矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-39_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-39\",\"order\":2,\"canonicalText\":\"譬之，是猶以塼塗塞江海也，以焦僥而戴太山也，蹎跌碎折，不待頃矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-39_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-39\",\"order\":3,\"canonicalText\":\"二三子之善於子宋子者，殆不若止之，將恐得傷其體也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-40_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-40\",\"order\":1,\"canonicalText\":\"子宋子曰：「人之情，欲寡，而皆以己之情，為欲多，是過也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-40_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-40\",\"order\":2,\"canonicalText\":\"」故率其羣徒，辨其談說，明其譬稱，將使人知情之慾寡也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-41_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-41\",\"order\":1,\"canonicalText\":\"應之曰：然則亦以人之情為目不欲綦色，耳不欲綦聲，口不欲綦味，鼻不欲綦臭，形不欲綦佚；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-41_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-41\",\"order\":2,\"canonicalText\":\"此五綦者，亦以人之情為不欲乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-42_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-42\",\"order\":1,\"canonicalText\":\"曰：「人之情，欲是已。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-42_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-42\",\"order\":2,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-43_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-43\",\"order\":1,\"canonicalText\":\"曰：若是，則說必不行矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-43_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-43\",\"order\":2,\"canonicalText\":\"以人之情為欲，此五綦者而不欲多，譬之，是猶以人之情為欲富貴而不欲貨也，好美而惡西施也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-43_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-43\",\"order\":3,\"canonicalText\":\"古之人為之不然。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-43_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-43\",\"order\":4,\"canonicalText\":\"以人之情為欲多而不欲寡，故賞以富厚而罰以殺損也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-43_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-43\",\"order\":5,\"canonicalText\":\"是百王之所同也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-43_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-43\",\"order\":6,\"canonicalText\":\"故上賢祿天下，次賢祿一國，下賢祿田邑，願愨之民完衣食。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-43_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-43\",\"order\":7,\"canonicalText\":\"今子宋子以是之情為欲寡而不欲多也，然則先王以人之所不欲者賞，而以人之慾者罰邪？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-43_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-43\",\"order\":8,\"canonicalText\":\"亂莫大焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-18_p-43_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-18\",\"passageId\":\"xunzi_ch-18_p-43\",\"order\":9,\"canonicalText\":\"今子宋子嚴然而好說，聚人徒，立師學，成文典，然而說不免於以至治為至亂也，豈不過甚矣哉！\",\"chunks\":[],\"tags\":[]}]}") as ChapterBundle
